/* l2tp.c - L2TP/IPsec module (see l2tp.h). Live L2TP needs the kernel's l2tp_ppp module and an LNS: only the generated files are tested here. */
#define _GNU_SOURCE
#include "l2tp.h"
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <limits.h>
#include <net/if.h>

const char *netman_l2tp_rundir = "/run/netman/vpn";
typedef struct { const char *server, *rid, *user, *pass, *psk, *routes; int mtu; } cfg;

static int detect(const char *t) { char ty[24]; return netman_vm_native(t, ty, sizeof ty) && !strcmp(ty, "l2tp"); }
static int load(const char *text, netman_vm_prof *p, cfg *c, char *err, size_t en)
{
	if (netman_vm_parse(text, p, err, en)) return -1;
	memset(c, 0, sizeof *c);
	c->server = netman_vm_get(p, "server"); c->rid = netman_vm_get(p, "remoteid"); c->user = netman_vm_get(p, "username"); c->pass = netman_vm_get(p, "password");
	c->psk = netman_vm_get(p, "psk"); c->routes = netman_vm_get(p, "routes");
	const char *m = netman_vm_get(p, "mtu"); c->mtu = m ? atoi(m) : 1280;
	if (!c->server || !netman_vm_tok_ok(c->server)) { snprintf(err, en, "Server missing or has odd characters"); goto bad; }
	if (c->rid && !netman_vm_tok_ok(c->rid)) { snprintf(err, en, "RemoteId has odd characters"); goto bad; }
	if (!c->user || !*c->user || !c->pass || !*c->pass) { snprintf(err, en, "Username and Password are required"); goto bad; }
	if (c->mtu < 576 || c->mtu > 1500) { snprintf(err, en, "MTU must be 576..1500"); goto bad; }
	if (c->routes) {
		char b[512], *it[32]; int n = netman_vm_split(c->routes, it, 32, b, sizeof b);
		if (n < 0) { snprintf(err, en, "Routes: too many or too long"); goto bad; }
		for (int i = 0; i < n; i++) if (netman_vm_cidr(it[i], NULL, 0, NULL, NULL)) { snprintf(err, en, "Routes: bad network %s", it[i]); goto bad; }
	}
	return 0;
bad:
	netman_vm_free(p); return -1;
}
static int validate(const char *t, char *err, size_t en) { netman_vm_prof p; cfg c; if (load(t, &p, &c, err, en)) return -1; netman_vm_free(&p); return 0; }
static void quote(const char *s, char *o, size_t n) { size_t j = 0; for (; *s && j + 3 < n; s++) { if (*s == '"' || *s == '\\') o[j++] = '\\'; o[j++] = *s; } o[j] = 0; }

int netman_l2tp_gen(const char *name, const char *text, char *out, size_t n, char *err, size_t en)
{
	netman_vm_prof p; cfg c; size_t o = 0;
	if (load(text, &p, &c, err, en)) return -1;
	o += (size_t)snprintf(out, n, "; generated by netman for profile %s - do not edit\n[global]\nport = 1701\nauth file = %s/%s.chap-unused\n\n"
		"[lac nm-%s]\nlns = %s\npppoptfile = %s/%s.ppp\nlength bit = yes\nrequire authentication = no\nrequire chap = yes\nrefuse pap = yes\nredial = no\nautodial = no\n",
		name, netman_l2tp_rundir, name, name, c.server, netman_l2tp_rundir, name);
	netman_vm_free(&p);
	if (o >= n) { snprintf(err, en, "config too large"); return -1; }
	return 0;
}
int netman_l2tp_ppp(const char *name, const char *text, char *out, size_t n, char *err, size_t en)
{
	netman_vm_prof p; cfg c; char u[300], w[600], ifn[20]; size_t o;
	if (load(text, &p, &c, err, en)) return -1;
	quote(c.user, u, sizeof u); quote(c.pass, w, sizeof w); netman_vm_ifname("l2-", name, ifn, sizeof ifn);
	o = (size_t)snprintf(out, n, "# generated by netman for profile %s - do not edit (holds the password: mode 0600)\nname \"%s\"\npassword \"%s\"\nifname %s\nlogfile %s/%s.log\n"
		"noauth\nrefuse-pap\nrefuse-eap\nrefuse-chap\nrequire-mschap-v2\nnoccp\nnobsdcomp\nnodeflate\nipcp-accept-local\nipcp-accept-remote\nusepeerdns\nmtu %d\nmru %d\nlcp-echo-interval 30\nlcp-echo-failure 4\n%s\n",
		name, u, w, ifn, netman_l2tp_rundir, name, c.mtu, c.mtu, c.routes ? "nodefaultroute" : "defaultroute");
	explicit_bzero(w, sizeof w);
	netman_vm_free(&p);
	if (o >= n) { snprintf(err, en, "config too large"); return -1; }
	return 0;
}
int netman_l2tp_ipsec(const char *name, const char *text, char *out, size_t n, char *err, size_t en)
{
	netman_vm_prof p; cfg c; char sec[400]; size_t o;
	if (load(text, &p, &c, err, en)) return -1;
	out[0] = 0;
	if (!c.psk) { netman_vm_free(&p); return 0; }
	netman_vm_hex(c.psk, sec, sizeof sec);
	o = (size_t)snprintf(out, n, "# generated by netman for profile %s - do not edit\nconnections {\n    nm-%s-l2tp {\n        version = 1\n        remote_addrs = %s\n        proposals = aes256-sha256-modp2048,aes128-sha1-modp1024,3des-sha1-modp1024\n"
		"        local {\n            auth = psk\n        }\n        remote {\n            auth = psk\n            id = %s\n        }\n        children {\n            nm-%s-l2tp {\n                mode = transport\n"
		"                local_ts = dynamic[udp/1701]\n                remote_ts = 0.0.0.0/0[udp/1701]\n                start_action = none\n            }\n        }\n    }\n}\nsecrets {\n    ike-nm-%s-l2tp {\n        id = %s\n        secret = %s\n    }\n}\n",
		name, name, c.server, c.rid ? c.rid : c.server, name, name, c.rid ? c.rid : c.server, sec);
	netman_vm_free(&p);
	if (o >= n) { snprintf(err, en, "config too large"); return -1; }
	return 0;
}

static int has_psk(const char *text) { netman_vm_prof p; cfg c; char e[64]; int r = 0; if (!load(text, &p, &c, e, sizeof e)) { r = c.psk != NULL; netman_vm_free(&p); } return r; }
static int xl2tpd_pid(const netman_vm_ctx *cx, const char *name, int *pid) { char pf[PATH_MAX]; netman_vm_path(pf, sizeof pf, cx, name, "pid"); return netman_vm_pid_alive(pf, pf, pid); }
static const char *state(const netman_vm_ctx *cx, const char *name)
{
	char ifn[20]; netman_vm_ifname("l2-", name, ifn, sizeof ifn);
	if (!xl2tpd_pid(cx, name, NULL)) return "down";
	if (if_nametoindex(ifn)) return "connected";
	if (netman_vm_log_has(cx, name, "authentication failed") || netman_vm_log_has(cx, name, "Authentication failed")) return "auth failed";
	return "connecting";
}
static int control(const netman_vm_ctx *cx, const char *name, const char *cmd)
{
	char cf[PATH_MAX], b[160]; netman_vm_path(cf, sizeof cf, cx, name, "control");
	int fd = open(cf, O_WRONLY | O_NONBLOCK | O_CLOEXEC); if (fd < 0) return -1;
	int n = snprintf(b, sizeof b, "%s nm-%s\n", cmd, name); ssize_t w = write(fd, b, (size_t)n); close(fd);
	return w == n ? 0 : -1;
}
static int server_ip(const char *host, char *ip, size_t n)
{
	char l[2][160]; if (netman_vm_ks_host(host, l, 1, "") < 1) return -1;
	(void)n; return sscanf(l[0], "%*s %*s %63s", ip) == 1 ? 0 : -1;
}
static int down(const netman_vm_ctx *cx, const char *name, const char *text);
static int up(const netman_vm_ctx *cx, const char *name, const char *path, const char *text, int wait)
{
	char err[160], *buf = malloc(8192), xc[PATH_MAX], pc[PATH_MAX], sc[PATH_MAX], ctl[PATH_MAX], pf[PATH_MAX], lf[PATH_MAX], sw[PATH_MAX], ifn[20], ip[64], undo[160] = "";
	int st, rc = 1; (void)path;
	if (!buf) return 1;
	if (xl2tpd_pid(cx, name, NULL)) { free(buf); return netman_vm_fail(cx, "%s is already running", name); }
	if (!netman_vm_which("xl2tpd", sw, sizeof sw)) { free(buf); return netman_vm_fail(cx, "%s: xl2tpd not found", name); }
	if (!netman_vm_which("pppd", sw, sizeof sw)) { free(buf); return netman_vm_fail(cx, "%s: pppd not found", name); }
	int psk = has_psk(text);
	if (psk && !netman_vm_which("swanctl", sw, sizeof sw)) { free(buf); return netman_vm_fail(cx, "%s: a PSK profile needs strongSwan's swanctl for the IPsec transport (not found); refusing to send L2TP in the clear", name); }
	if (netman_vm_mkdirs(cx->run_dir, 0700)) { free(buf); return netman_vm_fail(cx, "%s: %s", cx->run_dir, strerror(errno)); }
	netman_vm_path(xc, sizeof xc, cx, name, "xl2tpd.conf"); netman_vm_path(pc, sizeof pc, cx, name, "ppp"); netman_vm_path(sc, sizeof sc, cx, name, "swanctl.conf");
	netman_vm_path(ctl, sizeof ctl, cx, name, "control"); netman_vm_path(pf, sizeof pf, cx, name, "pid"); netman_vm_path(lf, sizeof lf, cx, name, "log");
	netman_vm_ifname("l2-", name, ifn, sizeof ifn);
	netman_l2tp_rundir = cx->run_dir;
	unlink(lf); unlink(ctl);
	if (netman_l2tp_gen(name, text, buf, 8192, err, sizeof err) || netman_vm_write(xc, buf, strlen(buf), 0600)) { free(buf); return netman_vm_fail(cx, "%s: %s", name, err[0] ? err : strerror(errno)); }
	if (netman_l2tp_ppp(name, text, buf, 8192, err, sizeof err) || netman_vm_write(pc, buf, strlen(buf), 0600)) { explicit_bzero(buf, 8192); free(buf); return netman_vm_fail(cx, "%s: %s", name, err[0] ? err : strerror(errno)); }
	if (psk) {
		netman_l2tp_ipsec(name, text, buf, 8192, err, sizeof err);
		if (netman_vm_write(sc, buf, strlen(buf), 0600)) { free(buf); return netman_vm_fail(cx, "%s: %s", sc, strerror(errno)); }
		char conn[110]; snprintf(conn, sizeof conn, "nm-%s-l2tp", name);
		char *a1[] = { "swanctl", "--load-all", "--file", sc, NULL }; char *a2[] = { "swanctl", "--initiate", "--child", conn, NULL };
		if ((st = netman_vm_spawn(a1, NULL, lf)) || (st = netman_vm_spawn(a2, NULL, lf))) { free(buf); unlink(sc); return netman_vm_fail(cx, "%s: IPsec transport SA failed (swanctl exit %d; see `netman vpn logs %s`)", name, st, name); }
	}
	explicit_bzero(buf, 8192); free(buf);
	{ netman_vm_prof p; netman_vm_parse(text, &p, err, sizeof err); const char *srv = netman_vm_get(&p, "server"); const char *rt = netman_vm_get(&p, "routes");
	  if (!rt && srv && !server_ip(srv, ip, sizeof ip)) netman_vm_defroute_host(ip, undo, sizeof undo);       /* the server stays reachable outside the tunnel */
	  netman_vm_free(&p); }
	if (undo[0]) { char uf[PATH_MAX]; netman_vm_path(uf, sizeof uf, cx, name, "undo"); netman_vm_write(uf, undo, strlen(undo), 0600); }
	char *xa[] = { "xl2tpd", "-c", xc, "-C", ctl, "-p", pf, NULL };
	if ((st = netman_vm_spawn(xa, NULL, lf))) return netman_vm_fail(cx, "%s: xl2tpd failed to start (exit %d; see `netman vpn logs %s`)", name, st, name);
	for (int i = 0; i < 25 && access(ctl, F_OK); i++) usleep(200000);
	if (control(cx, name, "c")) { netman_vm_fail(cx, "%s: cannot reach xl2tpd's control file", name); goto fail; }
	for (int i = 0; i < (wait > 0 ? wait : 30) * 5; i++) {
		const char *s = state(cx, name);
		if (!strcmp(s, "connected")) {
			netman_vm_prof p; if (!netman_vm_parse(text, &p, err, sizeof err)) { const char *rt = netman_vm_get(&p, "routes"); if (rt) netman_vm_routes(ifn, rt, 1); netman_vm_free(&p); }
			netman_vm_msg(cx, "%s: connected (%s)", name, ifn); return 0;
		}
		if (!strcmp(s, "down")) { netman_vm_fail(cx, "%s: xl2tpd exited; see `netman vpn logs %s`", name, name); goto fail; }
		if (!strcmp(s, "auth failed")) { netman_vm_fail(cx, "%s: authentication failed", name); goto fail; }
		usleep(200000);
	}
	netman_vm_fail(cx, "%s: no PPP interface after %d s (the LNS may not answer, or the kernel lacks l2tp_ppp); see `netman vpn logs %s`", name, wait > 0 ? wait : 30, name);
fail:
	(void)rc; down(cx, name, text);
	return 1;
}
static int down(const netman_vm_ctx *cx, const char *name, const char *text)
{
	int pid, was = xl2tpd_pid(cx, name, &pid); char pf[PATH_MAX], sc[PATH_MAX], pc[PATH_MAX], xc[PATH_MAX], uf[PATH_MAX], lf[PATH_MAX], conn[110];
	netman_vm_path(pf, sizeof pf, cx, name, "pid"); netman_vm_path(sc, sizeof sc, cx, name, "swanctl.conf"); netman_vm_path(pc, sizeof pc, cx, name, "ppp");
	netman_vm_path(xc, sizeof xc, cx, name, "xl2tpd.conf"); netman_vm_path(uf, sizeof uf, cx, name, "undo"); netman_vm_path(lf, sizeof lf, cx, name, "log");
	if (was) {
		control(cx, name, "d");
		usleep(300000);
		kill(pid, SIGTERM);
		for (int i = 0; i < 25 && kill(pid, 0) == 0; i++) usleep(200000);
		if (kill(pid, 0) == 0) kill(pid, SIGKILL);
	}
	if (access(sc, F_OK) == 0 && netman_vm_which("swanctl", conn, sizeof conn)) {
		snprintf(conn, sizeof conn, "nm-%s-l2tp", name);
		char *a[] = { "swanctl", "--terminate", "--ike", conn, NULL }; netman_vm_spawn(a, NULL, lf);
	}
	char *undo = netman_vm_slurp(uf, NULL, 256);
	if (undo) { char *a[8] = { "ip", NULL }, *sp = NULL, *t[3]; int k = 0; for (char *x = strtok_r(undo, " \n", &sp); x && k < 2; x = strtok_r(NULL, " \n", &sp)) t[k++] = x;
		if (k == 2) { a[1] = t[0]; a[2] = "route"; a[3] = "del"; a[4] = t[1]; a[5] = NULL; char o[200]; int st; netman_vm_run(a, NULL, o, sizeof o, 5000, &st); } free(undo); }
	unlink(uf); unlink(sc); unlink(pc); unlink(xc); unlink(pf); (void)text;
	if (!was) return netman_vm_fail(cx, "%s is not running", name);
	netman_vm_msg(cx, "%s: down", name); return 0;
}
static int ks(const char *text, char lines[][160], int max, char *tun, size_t tunn, const char *name)
{
	netman_vm_prof p; cfg c; char err[64]; int n;
	if (load(text, &p, &c, err, sizeof err)) return -1;
	netman_vm_ifname("l2-", name, tun, tunn);
	n = netman_vm_ks_host(c.server, lines, max - 1, "");
	if (n > 0 && c.psk) snprintf(lines[n++], 160, "rt ipsec exists accept");
	netman_vm_free(&p); return n;
}
static int info(const netman_vm_ctx *cx, const char *name, const char *text)
{
	netman_vm_prof p; cfg c; char err[96], ifn[20]; netman_vm_ifname("l2-", name, ifn, sizeof ifn);
	netman_vm_msg(cx, "type         l2tp%s", has_psk(text) ? "/ipsec" : " (no IPsec: plain L2TP is not encrypted)");
	netman_vm_msg(cx, "state        %s", state(cx, name));
	if (load(text, &p, &c, err, sizeof err)) { netman_vm_msg(cx, "config       %s", err); return 0; }
	netman_vm_msg(cx, "server       %s", c.server); netman_vm_msg(cx, "interface    %s", ifn);
	netman_vm_msg(cx, "routing      %s", c.routes ? "split tunnel (only Routes go through the VPN)" : "full tunnel (default route through the VPN)");
	netman_vm_free(&p); return 0;
}
const netman_vpnmod netman_l2tp_mod = { "l2tp", ".vpn", "xl2tpd", "vpn.l2tp", detect, validate, netman_l2tp_gen, up, down, state, ks, info };
